class Node:
    def __init__(self, value, children=None):
        self.value = value
        self.children = children or []


def flatten(node):
    out = []
    stack = [node]
    while stack:
        current = stack.pop()
        out.append(current.value)
        for child in reversed(current.children):
            stack.append(child)
    return out


def depth(node):
    if node is None:
        return 0
    max_depth = 0
    stack = [(node, 1)]
    while stack:
        current, d = stack.pop()
        if d > max_depth:
            max_depth = d
        for child in current.children:
            stack.append((child, d + 1))
    return max_depth

